#!/usr/bin/env python3
"""Regression tests for dashboard counting and comment scanning."""

import contextlib
import io
import json
from pathlib import Path
import tempfile
import unittest
from unittest import mock

import codebase_metrics as metrics


class MetricsTest(unittest.TestCase):
    def test_comments_and_quotes(self):
        cases = [
            ('int x; // comment', 'C++', False, ('int x; ', True, False)),
            ('"// quoted" /* comment */ x', 'C++', False,
             ('"// quoted"  x', True, False)),
            ('/* open', 'C++', False, ('', True, True)),
            ('close */ x', 'C++', True, (' x', True, False)),
            ('', 'C++', True, ('', True, True)),
            ('<!-- comment --> x', 'HTML', False, (' x', True, False)),
            ('select "--" -- comment', 'SQL', False, ('select "--" ', True, False)),
            ('x # comment', 'Python', False, ('x ', True, False)),
        ]
        # An unterminated quote, including a trailing escape, protects markers.
        for quote in ("'", '"', '`'):
            line = quote + "# // <!-- -- trailing" + chr(92)
            cases.append((line, 'Python', False, (line, False, False)))
            line = quote + chr(92) + quote + '# still quoted' + quote
            cases.append((line, 'Python', False, (line, False, False)))
        for line, language, block, expected in cases:
            with self.subTest(line=line, language=language):
                self.assertEqual(metrics.strip_comments(line, language, block), expected)


    def test_inventory_and_obsolete_window(self):
        data = ('# deprecated\n' + '\n' * 5 + 'def inside(): pass\n'
                + 'def outside(): pass\n' + 'x = "# Google" # comment\n').encode()
        result = metrics.analyze_blob(data, 'Python')
        self.assertEqual(result['actual_loc'], 3)
        self.assertEqual(result['lines_of_code'], 4)
        self.assertEqual(result['comment_lines'], 2)
        self.assertEqual(result['lines_without_comment_only_lines'], 3)
        self.assertEqual(result['google_mentions'], 1)
        self.assertEqual(result['obsolete'], [[7, 'inside']])

    def test_scope(self):
        cases = {
            'src/main.cc': 'maintained', 'build/build.py': 'maintained',
            'tools/analyzer.py': 'maintained', 'src/foo_unittest.cc': 'tests',
            'src/ThingTest.java': 'tests', 'tests/example.py': 'tests',
            'third_party/lib/foo.cc': 'vendored', 'src/vendor/lib.cc': 'vendored',
            'src/gen/foo.cc': None, 'src/generated/foo.cc': None,
            'src/foo.min.js': None, 'src/foo.bundle.js': None,
            'src/foo.pb.cc': None, 'src/foo_pb2.py': None,
            'src/test/data/foo.cc': None, 'src/testdata/foo.cc': None,
            'src/fixtures/foo.py': None, 'README.md': None,
            'BUILD.gn': None, 'config.xml': None, 'package-lock.json': None,
            'image.png': None, 'metrics.json': None,
        }
        for path, category in cases.items():
            with self.subTest(path=path):
                self.assertEqual(metrics.classify_path(path)[0], category)
        self.assertEqual(metrics.analyze_blob(b'// Generated by protoc\nint x;', 'C++'),
                         {'excluded': 'generated'})
        self.assertEqual(metrics.analyze_blob(b'x\0y', 'C++'), {'excluded': 'binary'})
        self.assertNotIn('excluded', metrics.analyze_blob(
            b'message = "Generated by the user"\n', 'Python'))


class HistoryTest(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.path = Path(self.directory.name) / 'metrics-history.json'

    def snapshot(self, updated, loc=10, version=1):
        result = metrics.analyze_blob(b'x = 1\n', 'Python')
        category = {**result, 'files': 1, 'actual_loc': loc, 'obsolete_functions': 0,
                    'languages': [{'name': 'Python', 'lines': loc}]}
        return {'updated': updated, 'commit': str(loc), 'counting_rules_version': version,
                'categories': {name: category.copy() for name in ('maintained', 'tests', 'vendored')},
                'configuration_files': 2, 'root_folder_count': 1, 'excluded_files': {'binary': 3}}

    def update(self, *args, **kwargs):
        return metrics.update_history(self.path, self.snapshot(*args, **kwargs))['records']

    def test_daily_replacement_and_gaps(self):
        self.assertIsNone(self.update('2026-11-08T12:00:00Z')[0]['delta'])
        self.update('2026-11-09T12:00:00Z', 15)
        records = self.update('2026-11-09T16:00:00Z', 18)
        self.assertEqual(len(records), 2)
        self.assertEqual(records[1]['delta']['categories']['maintained']['actual_loc'], 8)
        # Stale retries do not roll back the current daily snapshot.
        self.assertEqual(self.update('2026-11-09T14:00:00Z', 16), records)
        records = self.update('2026-11-12T00:15:00Z', 20)
        self.assertEqual(records[2]['days_since_previous'], 3)
        self.assertEqual(records[2]['previous_date'], '2026-11-09')
        self.assertEqual(records[2]['delta']['categories']['maintained']['actual_loc'], 2)

    def test_rules_changes_and_out_of_order_updates(self):
        self.update('2026-11-08T12:00:00Z', 10)
        self.update('2026-11-10T12:00:00Z', 30)
        records = self.update('2026-11-09T12:00:00Z', 25)
        self.assertEqual(records[2]['delta']['categories']['maintained']['actual_loc'], 5)
        records = self.update('2026-11-11T12:00:00Z', 90, version=2)
        self.assertIsNone(records[3]['delta'])
        self.assertIsNone(records[3]['previous_date'])
        records = self.update('2026-11-12T12:00:00Z', 95, version=2)
        self.assertEqual(records[4]['delta']['categories']['maintained']['actual_loc'], 5)

    def test_utc_dates_and_language_removal(self):
        self.update('2026-11-09T00:15:00+02:00')
        snapshot = self.snapshot('2026-11-09T01:15:00Z')
        snapshot['categories']['maintained']['languages'] = [{'name': 'Rust', 'lines': 8}]
        records = metrics.update_history(self.path, snapshot)['records']
        self.assertEqual([r['date'] for r in records], ['2026-11-08', '2026-11-09'])
        self.assertEqual(records[1]['delta']['categories']['maintained']['languages'],
                         {'Python': -10, 'Rust': 8})

    def test_entrypoint_writes_history_with_snapshot(self):
        page = Path(self.directory.name) / 'template.html'
        page.write_text('<html>dashboard</html>')
        output = Path(self.directory.name) / 'output'
        snapshot = self.snapshot('2026-11-09T12:00:00Z')
        snapshot.update(actual_loc=10, scan={'elapsed_seconds': 0.1})
        with mock.patch.object(metrics, 'PAGE', page), \
             mock.patch.object(metrics, 'build_metrics', return_value=snapshot), \
             mock.patch('sys.argv', ['metrics', str(output), '--cache', str(output / 'cache')]), \
             contextlib.redirect_stdout(io.StringIO()):
            metrics.main()
        self.assertEqual((output / 'index.html').read_text(), page.read_text())
        self.assertEqual(json.loads((output / 'metrics.json').read_text()), snapshot)
        history = json.loads((output / 'metrics-history.json').read_text())
        self.assertEqual(history['records'][0]['date'], '2026-11-09')
        self.assertEqual(history['records'][0]['counting_rules_version'], 1)

    def test_invalid_history_is_preserved(self):
        self.path.write_text('{broken', encoding='utf-8')
        with self.assertRaises(json.JSONDecodeError):
            self.update('2026-11-09T12:00:00Z')
        self.assertEqual(self.path.read_text(), '{broken')



class GitIntegrationTest(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)
        self.patch = mock.patch.object(metrics, 'ROOT', self.root)
        self.patch.start()
        self.addCleanup(self.patch.stop)
        self.git('init', '-q')
        self.git('config', 'user.name', 'Metrics test')
        self.git('config', 'user.email', 'test@example.invalid')
        self.cache = self.root / '.git/cache.sqlite3'

    def git(self, *args, data=None):
        return metrics.git(*args, input_bytes=data)

    def write(self, path, data):
        target = self.root / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)

    def commit(self):
        self.git('add', '.')
        self.git('commit', '-qm', 'fixture')

    def scan(self):
        with contextlib.redirect_stdout(io.StringIO()):
            return metrics.build_metrics('HEAD', self.cache)

    def test_cold_warm_and_incremental_committed_snapshot(self):
        content = b'# deprecated\ndef old(): pass\n'
        self.write('src/main.py', content)
        self.write('src/duplicate.py', content)
        self.write('tests/main_test.py', content)
        self.write('third_party/library.py', content)
        self.write('test/data/fixture.py', content)
        self.write('src/generated/foo.py', content)
        self.write('src/autogen.py', b'# Automatically generated\nx = 1\n')
        self.write('src/binary.py', b'x\0y')
        self.write('README.md', b'Google docs\n')
        self.write('BUILD.gn', b'source_set("foo") {}\n')
        # Tracked source is retained even if a working-tree ignore rule matches.
        self.write('.gitignore', b'*.py\n')
        self.git('add', '-f', 'src', 'tests', 'third_party', 'test')
        self.commit()
        # Add a symlink entry without needing Windows symlink privileges.
        oid = self.git('hash-object', '-w', '--stdin', data=b'src/main.py').decode().strip()
        self.git('update-index', '--add', '--cacheinfo', '120000', oid, 'link.py')
        self.git('commit', '-qm', 'symlink')
        self.write('src/main.py', b'local dirty contents must not count\n')
        self.write('untracked.py', b'not committed\n')
        first = self.scan()
        self.assertEqual(first['actual_loc'], 2)
        self.assertEqual(first['categories']['tests']['actual_loc'], 1)
        self.assertEqual(first['categories']['vendored']['actual_loc'], 1)
        self.assertEqual(first['configuration_files'], 2)  # BUILD.gn, .gitignore
        self.assertEqual(first['excluded_files']['generated'], 2)
        self.assertEqual(first['excluded_files']['fixture'], 1)
        self.assertEqual(first['excluded_files']['binary'], 1)
        self.assertEqual(first['scan']['read_blobs'], 3)
        self.assertEqual(first['obsolete_functions'], 2)
        with mock.patch.object(metrics, 'read_blobs', wraps=metrics.read_blobs) as reader:
            second = self.scan()
            reader.assert_called_once_with([])
        self.assertEqual(second['scan']['read_blobs'], 0)
        self.assertEqual(second['scan']['cached_paths'], 6)
        for key in ('categories', 'excluded_files', 'languages', 'actual_loc',
                    'obsolete_function_examples'):
            self.assertEqual(first[key], second[key])
        # Restore dirty file and move a cached blob from production into tests.
        self.write('src/main.py', content)
        self.git('mv', 'src/duplicate.py', 'tests/renamed_test.py')
        self.git('rm', 'third_party/library.py')
        self.write('src/new.py', b'x = 1\ny = 2\n')
        self.git('add', '-f', 'src/new.py')
        self.git('commit', '-qm', 'incremental')
        third = self.scan()
        self.assertEqual(third['scan']['read_blobs'], 1)
        self.assertEqual(third['actual_loc'], 3)
        self.assertEqual(third['categories']['tests']['actual_loc'], 2)
        self.assertEqual(third['categories']['vendored']['actual_loc'], 0)
        self.assertEqual(third['obsolete_function_examples'],
                         [{'path': 'src/main.py', 'line': 2, 'name': 'old'}])
        # Scanner version changes must invalidate even unchanged blobs.
        cache = metrics.BlobCache(self.cache)
        cache.db.execute("UPDATE metadata SET version='old-scanner'")
        cache.close()
        fourth = self.scan()
        self.assertEqual(fourth['scan']['cached_paths'], 0)
        self.assertEqual(fourth['categories'], third['categories'])

    def test_identical_blobs_in_different_languages(self):
        self.write('main.py', b'# comment\n')
        self.write('main.cc', b'# comment\n')
        self.commit()
        first = self.scan()
        self.assertEqual(first['scan']['read_blobs'], 1)
        self.assertEqual(first['actual_loc'], 1)
        second = self.scan()
        self.assertEqual(second['scan']['cached_paths'], 2)
        self.assertEqual(second['categories'], first['categories'])

    def test_batch_pipe_backpressure_and_failure(self):
        oids = []
        expected = {}
        for i in range(250):
            data = (str(i) + '\n').encode() * 8000
            oid = self.git('hash-object', '-w', '--stdin', data=data).decode().strip()
            oids.append(oid)
            expected[oid] = data
        self.assertEqual(dict(metrics.read_blobs(oids)), expected)
        with self.assertRaises(RuntimeError):
            list(metrics.read_blobs(['0' * 40]))


if __name__ == '__main__':
    unittest.main()
